// shared/test-vectors/prior.json: TypeScript-only prior vectors (the prior is TypeScript only, spec 10.5),
// generated by tools/vectors/make_vectors.py from the Python reference.
import { describe, expect, it } from "vitest";
import vectors from "../../test-vectors/prior.json";
import { linearWeights } from "../src/index";
import { expectVector } from "./expectVector";

describe("prior vectors", () => {
  it("has the linear-weight cases", () => {
    expect(vectors.linearWeights.map(c => c.name)).toEqual(["dense_neutral", "exact_075_neutral", "sparse_formula", "all_far_unchanged", "zero_mass_unchanged"]);
  });
  for (const c of vectors.linearWeights) {
    it(c.name, () => {
      const { mass, nearFrac, nearShare, farShare } = c.input;
      expectVector(linearWeights(mass, nearFrac, nearShare, farShare), c.expected);
    });
  }
});
